    OfflineBookQuestion(5,"math",8,"প্রাথমিক গণিত","যাতায়াত করবে?","এটি প্রাথমিক গণিত বইয়ের পৃষ্ঠা 8-এর অনুশীলনী। পৃষ্ঠার নির্দেশনা, ছবি, ছক ও দেওয়া তথ্য ধাপে ধাপে অনুসরণ করে কাজটি সম্পন্ন করো এবং বইয়ের উদাহরণের সঙ্গে মিলিয়ে যাচাই করো।"),
    OfflineBookQuestion(5,"math",8,"প্রাথমিক গণিত","তোমার কি মনে পড়ে?","বইয়ের প্রাসঙ্গিক তথ্য: গাণিতিক বাক্য ৪৬১৪ x ৩৬৫ = ৪৬১৪ ৫ ২৩০৭০ বছরে ১৬৮৪১১০টি গাড়ি চলাচল করে। ১৬৮৪১১০ আমরা চতুর্থ শ্রেণিতে গুণ্য, গুণক ও গুণফল শিখেছি।\n\nএই তথ্য এবং পৃষ্ঠা 8-এর ছবি, ছক বা উদাহরণ ব্যবহার করে পূর্ণ বাক্যে উত্তর দাও।"),
    OfflineBookQuestion(5,"math",9,"প্রাথমিক গণিত","করলেন?","বইয়ের প্রাসঙ্গিক তথ্য: ১ একজন পাইকারি মোবাইল ফোন বিক্রেতা কোনো একমাসে প্রতিটি ৮৫৩৬ টাকা মূল্যের ৯৭২টি মোবাইল ফোন বিক্রয় করলেন। তিনি এঁ মাসে মোট কত টাকার মোবাইল ফোন বিক্রয়\n\nএই তথ্য এবং পৃষ্ঠা 9-এর ছবি, ছক বা উদাহরণ ব্যবহার করে পূর্ণ বাক্যে উত্তর দাও।"),
    OfflineBookQuestion(5,"math",12,"প্রাথমিক গণিত","9800 x ২৯০০ গুণটি আমরা কীভাবে করব?","এটি প্রাথমিক গণিত বইয়ের পৃষ্ঠা 12-এর অনুশীলনী। পৃষ্ঠার নির্দেশনা, ছবি, ছক ও দেওয়া তথ্য ধাপে ধাপে অনুসরণ করে কাজটি সম্পন্ন করো এবং বইয়ের উদাহরণের সঙ্গে মিলিয়ে যাচাই করো।"),
    OfflineBookQuestion(5,"science",7,"প্রাথমিক বিজ্ঞান","P জীবের আবাসস্বলগুলো কী কী?","বইয়ের প্রাসঙ্গিক তথ্য: ধরনের উদ্ভিদ ও প্রাণী রয়েছে। কোনো কোনো জীব স্বলভাগ বা মাটিতে বাস করে। কেউ আবার পানিতে বা মাটি ও পানি উভয় স্থানে বসবাস করে। কোনো কোনো জীবের প্রয়োজন ছায়াযুত্ত পরিবেশ, আবার কারো প্রয়োজন আলো আছে এমন পরিবেশ। এই অধ্যায়ে আমরা বিভিন্ন জীবের আবাসম্বল, বিভিন্ন আবাসস্থলে উদ্ভিদ ও প্রাণীর ধরন এবং পরিবেশে তাদের টিকে থাকার কৌশল ইত্যাদি সম্পর্কে জানব। যেখানে কোনো জীব স্বচ্ছন্দে বসবাস করতে পারে সেটাই জীবের আবাসস্বল।\n\nএই তথ্য এবং পৃষ্ঠা 7-এর ছবি, ছক বা উদাহরণ ব্যবহার করে পূর্ণ বাক্যে উত্তর দাও।"),
    OfflineBookQuestion(5,"science",11,"প্রাথমিক বিজ্ঞান","' বিভিন্ন পরিবেশে জীব কীভাবে নিজেকে খাপ খাওয়ায়?","বইয়ের প্রাসঙ্গিক তথ্য: পানির গভীরতার সাথে সাথে এখানে জীববৈচিত্র্যের পরিবর্তন হয়। এখানকার বিশেষ উদ্ভিদ হলো watt, AAG, হিজল, করচ, বরুন ইত্যাদি। এ পরিবেশে বিভিন্ন ধরনের প্রাণী যেমন- মাছ, সাপ, ব্যাঙ এবং জলচর পাখি দেখা যায়। নির্দিষ্ট বাসস্থানের বা পরিবেশের সাথে জীবের খাপ খাইয়ে বেঁচে থাকার প্রক্রিয়াকে অভিযোজন বলে। পরিবেশে খাপ খাইয়ে নেওয়ার জন্য বিভিন্ন ধরনের উদ্ভিদের মধ্যে বিশেষ বিশেষ কিছু বৈশিষ্ট্য লক্ষ\n\nএই তথ্য এবং পৃষ্ঠা 11-এর ছবি, ছক বা উদাহরণ ব্যবহার করে পূর্ণ বাক্যে উত্তর দাও।"),
    OfflineBookQuestion(5,"science",11,"প্রাথমিক বিজ্ঞান","অংশ থাকার কারণ কী? কচুরিপানায় এই ফাঁপা অংশ থাকা-সম্পর্কিত ধারণা নিচের ফাঁকা জায়গায় লেখো।","এটি প্রাথমিক বিজ্ঞান বইয়ের পৃষ্ঠা 11-এর অনুশীলনী। পৃষ্ঠার নির্দেশনা, ছবি, ছক ও দেওয়া তথ্য ধাপে ধাপে অনুসরণ করে কাজটি সম্পন্ন করো এবং বইয়ের উদাহরণের সঙ্গে মিলিয়ে যাচাই করো।"),
